INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(72100, 0, 721, 0, 0, 0, 'Gnomeregan', 'Gnomeregan was the capital of the gnomes, a city of workshops and machine halls dug deep beneath the western hills of Dun Morogh, lost since troggs broke in from below and the gnomes'' own purge poisoned it. Mekgineer Thermaplugg now rules what is left from its lowest halls. The gnomes who stayed behind are leprous, their minds so clouded by sickness that they still fight the invasion, cutting down every stranger as a trogg and swearing that no gnome will be left behind. The troggs never left either. Irradiated, they swarm the halls, and when one dies its blood sprays into the air, irradiating whoever it splashes, friend or foe. Slimes, lurkers and horrors ooze with green fallout, and the city''s machines still patrol. Exiles come to recover what was left behind or to strike at the traitor, goblins come for the secrets of a new gnomish rig, and a few holdouts still cling to a room of their own.', 'warcraft.wiki.gg/wiki/Gnomeregan_(instance) (gnomish capital, trogg invasion, irradiated, Thermaplugg in the deepest court, mutant troggs, Dark Iron agents and ambassador near the Tinkers'' Court); dun_morogh.json 113 (outdoor entrance in the western hills; failed radiation purge, told there); creature_text 6222, 6223, 6224, 7603 (No gnome will be left behind; the troggs never stop coming; this sickness clouds my vision but I know you must be a trogg); creature_text 6206, 6207, 6211, 6212, 6222-6224, 6228, 6391, 7603 (splashed by the blood and becomes irradiated, on hit by spell 9798 Radiation) and 6329 (Irradiated Pillager: blood sprays into the air); DB spawns on map 90: Irradiated Pillager 6329 x46, Caverndeep Burrower/Reaver/Ambusher, Irradiated Slime 6218, Corrosive Lurker 6219, Irradiated Horror 6220, Leprous Assistant/Technician/Machinesmith/Defender, Mechano-Tank/Flamewalker/Frostwalker, Mechanized Sentry/Guardian, Dark Iron Agent 6212 x34 (x -771 to -626, z about -306), Mekgineer Thermaplugg 7800 (z -325); quests 2841 (goblins want the new rig''s blueprints), 2922, 2924, 2929, 2930 descriptions (the exiles'' errands, told in ironforge.json); quest 2951 description (gnomes holding out against the madness outside the room)'),
(72101, 1, 721, 1, 0, 0, 'The Holdouts'' Room', 'In the middle of the ruined city, one room still holds out against the madness outside it. A band of gnome holdouts, warriors, medics and technicians who stand with the exiles of Gnomeregan, keeps it, and even a mailbox stands among them. Tink Sprocketwhistle sells engineering supplies from the room, though he admits that business has not been good of late. Against the walls stand three Sparklematic 5200s, gnomish machines whose plaques promise to scrub the grime from any valuable for three silver coins and hand it back clean and shiny.', 'quest 2951, 4601, 4602 descriptions (gnomes holding out against the madness outside the room; the Sparklematic plaque); gameobjects 142487, 175084, 175085 The Sparklematic 5200, all at z -193.7 beside the holdouts (x -497 to -550, y 163 to 206); 144179 Mailbox at -548,167; DB spawns: Holdout Warrior 6391, Holdout Medic 6392, Holdout Technician 6407 and Tink Sprocketwhistle 9676 at z -193.6, x -491 to -566, y 167 to 223; templates 23 and 875 are faction 54 Gnomeregan Exiles; npc_text 3156 (Tink: business hasn''t been all that good as of late), creature_template 9676 subname Engineering Supplies; warcraft.wiki.gg/wiki/Clean_Zone and Gnomeregan_(instance) (the room''s NPCs and machines; its name not used, see notes)'),
(72102, 2, 721, 1, 0, 0, 'Mekgineer Thermaplugg', 'Mekgineer Thermaplugg rules Gnomeregan from its deepest chamber. To the gnomes exiled in Ironforge he is the betrayer, the madman who turned on his own people and now holds their ruined city for himself. Leprous gnomes and the city''s machines guard the ways to his court. The goblins of Orgrimmar know him for something else: near him stands a safe holding the plans of a new gnomish rig, and he alone knows its combination.', 'quest 2904 reward text (that good-for-nothing backstabber, Mekgineer Thermaplugg); quest 2841 description (blueprints locked in a safe near Thermaplugg; combination known only to him); gameobject 142477 Thermaplugg''s Safe at -460,635, beside his spawn at -531,670 (map 90); creature 7800 single spawn on map 90; creature_template faction 63 (faction 53), shared with the leper gnomes, the machines and the Dark Iron agents; warcraft.wiki.gg/wiki/Mekgineer_Thermaplugg (Gelbin''s chief advisor; rules from the Tinkers'' Court); quest 2929 description (betrayed me and the entire gnomish people; that madman is in charge), pointed to in one phrase; told in ironforge.json 153703 and 153713'),
(72103, 2, 721, 2, 0, 0, 'Blastmaster Emi Shortfuse', 'Blastmaster Emi Shortfuse, a gnome, keeps her post at the end of the first hall inside the gates. She is so desperate for help, she admits, that she would take it from a two-headed ogre. The attempts to wipe out the troggs contaminated the whole city, but the scientists who fled to Ironforge are working on a cure for the fallout sickness, and she believes that if the invasion can be stopped, Gnomeregan might yet be retaken. She means to survey the tunnels, find where the troggs are coming from and stop them.', 'npc_text 1693 (gossip_menu 1080: two-headed ogre; overrun by troggs; attempts to wipe them out resulted in mass contamination; scientists in Ironforge working on a cure; stop the invasion and the city may be retaken); creature_text 7998 groups 0-1 (evaluate these tunnels; find out where these troggs are coming from and put a stop to the invasion); creature 7998 single spawn on map 90 at -515,-139; warcraft.wiki.gg/wiki/Blastmaster_Emi_Shortfuse (gnome; end of the first hall on the left after entering)'),
(72104, 2, 721, 3, 0, 0, 'Kernobee', 'Kernobee, a goblin, lies battered in a side room of the city, among the troggs he was thrown to. He was captured by Dark Iron dwarves, beaten to within an inch of his life and left there to die. Once he comes to, he wants only one thing: to be led to the Clockwerk Run exit and out of Gnomeregan. If he lives, he means to hurry to Ratchet and warn Tinkerwiz that the Dark Irons are involved in making the new gnomish rig, and he asks his rescuer to let Scooty in Booty Bay know where he has gone.', 'quest 2904 description and log text (captured by dark iron dwarves, beaten, thrown in with the troggs; lead me to the exit; tell Scooty I went to Ratchet to warn Tinkerwiz of the dark iron''s involvement in the making of that super rig; Clockwerk Run exit); creature 7850 single spawn on map 90 at -640,72; creature_template faction 35, friendly to both; creature 3494 Tinkerwiz, Engineering Trainer, in Ratchet; 7853 Scooty, Chief Engineer, in Booty Bay; warcraft.wiki.gg/wiki/Kernobee (goblin; found in a small room off the Dormitory)'),
(72105, 3, 721, 1, 2, 0, 'Rig Wars', 'In Orgrimmar the goblin engineer Nogg nurses a grudge. Two years ago, he says, gnomish technology was good for little but a punch line; now the gnomes have built a new rig better than every goblin shredder model put together. Nogg wants its blueprints. They are locked in a safe near Mekgineer Thermaplugg, and the combination is known only to Thermaplugg himself, so whoever goes after the plans must first take the combination from him, by whatever means it takes, then crack the safe and bring the blueprints back to Orgrimmar.', 'quest 2841 description and log text; quest 2842 description and reward text; quest 2843 description (transponder calibrated; return by the pad in Gnomeregan); creature 3412 Nogg, Apprentice Engineer, and 3413 Sovik in Orgrimmar; 7853 Scooty in Booty Bay; no zone file uses 2841-2843'),
(72106, 3, 721, 2, 0, 0, 'The Dark Iron Hand', 'Dark Iron dwarves have no place in a gnomish city, yet here they are, dozens of them. Their agents hold the last tunnels before Thermaplugg''s court, standing among the city''s mechanized guardians and arcane nullifiers, which leave them be. They make no secret of their pride: never cross a Dark Iron, they warn, and they call on intruders to feel the power of the Dark Iron dwarves while they sow land mines in their path. Who sent them, and what their clan wants from the gnomes'' ruined city, none of them will say.', 'creature_text 6212 group 1 (Never cross a Dark Iron; Feel the power of the Dark Iron Dwarves) and smart_scripts 6212 (Dark Iron Land Mine); creature_loot_template 6212 (Grime-Encrusted Object 9308, Grime-Encrusted Ring 9326); item 9326 starts quest 2945; quest 2945 description (ring from the corpse of one of the Dark Iron dwarves); quests 2904, 2947, 2949 description and reward text; warcraft.wiki.gg/wiki/Mekgineer_Thermaplugg (Dark Iron agents and an ambassador in Gnomeregan; Dark Irons helped with the super rig); DB spawns: Dark Iron Agent 6212 x34 on map 90 only, x -771 to -626, y 531 to 713, z -334 to -273, in the same tunnels as Mechanized Guardian 6234 x15 and Arcane Nullifier X-21 6232 x7 (all faction template 63), before Thermaplugg''s door 142207 at -619,691'),
(72107, 3, 721, 3, 0, 0, 'The Machines of Gnomeregan', 'Gnomeregan was a city of machines, and its machines are still running. Mechano-tanks, flamewalkers and frostwalkers still stalk its halls beside mechanized sentries and guardians, arcane nullifiers and peacekeeper security suits, and now they fight alongside the leprous gnomes against anyone who comes in. Mobile alert systems sound the intruder alarm and call lepers to their aid. Their keepers have not abandoned them either: when a fight begins, leprous machinesmiths supercharge the sentries and flamewalkers at their side. Deeper in, a few of the old city''s greatest machines still stand their posts.', 'DB spawns on map 90: Mechano-Tank 6225, Mechano-Flamewalker 6226, Mechano-Frostwalker 6227, Mechanized Sentry 6233, Mechanized Guardian 6234, Arcane Nullifier X-21 6232, Peacekeeper Security Suit 6230, Mobile Alert System 7849; faction template 63 shared with the leper gnomes; quest 2928 description (bots and mechs roam around that place like cattle on an open range); creature_text 7800 group 1 (My machines are the future), not used in the opening; smart_scripts 7849 and creature_text 7849 (Mobile Alert System: Warning! Intruder alert!; summons Leprous Assistant 7603 and Leprous Defender 6223); smart_scripts 6224 (Leprous Machinesmith: in combat, Supercharge on the nearest Mechanized Sentry 6233 or Mechano-Flamewalker 6226), not changed by the module');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(72100, 1, 0, 255, 'The poison has a body of its own here. Early in the descent waits Viscous Fallout, a heaving mass of radioactive ooze that wraps itself in a cloud of radiation and hurls corrosive slime and toxic volleys at anyone who comes near. Broken apart at last, it leaves the hall it haunted, though not the rest of the city, a little less deadly.', 'smart_scripts 7079 (Radiation Cloud aura, Toxic Volley, Corrosive Ooze); creature 7079 single spawn on map 90 at -471,48 (warcraft.wiki.gg/wiki/Gnomeregan_(instance): Hall of Gears, early mini-boss)'),
(72102, 1, 0, 255, 'Thermaplugg met intruders in his final chamber with a cry of usurpers, claiming Gnomeregan as his own. As he fought, the gnome faces set in the chamber walls woke at his command and loosed walking bombs on his foes, while he boasted that his machines were the future and would destroy them all, and whenever one of his foes fell he shrieked for more explosions. In the end he fell himself, in the hall he had claimed, and the bombs stopped with him.', 'creature_text 7800 groups 0-2 (Usurpers! Gnomeregan is mine; My machines are the future; Explosions! MORE explosions); group 3 (And STAY dead) is never called by his script and is not used; smart_scripts 7800 (say 0 on aggro, say 1 every 10 s in combat, say 2 on killing a foe; Activate Bomb on the gnome faces, Knock Away; on death set data on the faces and despawn Walking Bombs 7915); smart_scripts 142208-142213 Gnome Face 01-06 (hit by his spell: summon Walking Bomb 7915; reset on his death); gameobjects 142207 The Final Chamber (door), 142208-142213 Gnome Face 01-06'),
(72103, 1, 0, 255, 'Emi led her helpers to a tunnel wall where the troggs were breaking in. While they held off wave after wave, she set charge after charge and brought the tunnel down, then heard more troggs at a second breach and began again. Last came Grubbis with his beast Chomper, roaring that they came from below and could never be stopped. When he and his beast had fallen, Emi blasted the final hole shut and cheered her helpers: because of them, she said, her people stood a chance of retaking their city.', 'creature_text 7998 groups 5-20 (tunnel wall, trogg incursion, one charge not enough, more troggs, final charge, fire in the hole, my people stand a chance of retaking our beloved city, three cheers); creature_text 7361 (We come from below! You can never stop us!); creature_summon_groups 7998 group 4 (Grubbis 7361 and Chomper 6215, beast); smart_scripts 7361 (death sets instance data, Emi despawns); warcraft.wiki.gg/wiki/Blastmaster_Emi_Shortfuse (gnome; two spots where the troggs began invading; Grubbis and Chomper at the end); smart_scripts 7998 (waypoints, summon groups 1-4, cave-ins 146086 and 146085; at the last waypoint she summons group 4, sets phase 1 and attacks Grubbis; on evade in phase 1, lines 17-20, explosion 12159 closing 146085, Red Streaks Firework, despawn after 20 s)'),
(72104, 1, 0, 255, 'Kernobee made it out. His rescuers brought him safely to the Clockwerk Run exit, and from there he set off for Ratchet with his warning. In Booty Bay, Scooty could hardly believe that Kernobee was alive. Grateful all the same, he rewarded the rescuers with something to give them an edge should they go back into Gnomeregan to face the one he calls a good-for-nothing backstabber, Mekgineer Thermaplugg.', 'instance_gnomeregan.cpp npc_kernobee (follows the player after the accept; at the exit point, credit to the whole group, then despawn; the script speaks no lines); quest 2904 description (tell Scooty I went to Ratchet to warn Tinkerwiz), completion text (Eh? Kernobee is alive??) and reward text (these might give you the edge; that good-for-nothing backstabber, Mekgineer Thermaplugg)'),
(72105, 1, 0, 255, 'Sovik, who sells engineering supplies at Nogg''s side, had a faster road in mind. As soon as word of the rig came from Kernobee, he and Scooty, chief engineer in Booty Bay, began the Transpolyporter 6000, the goblins'' way straight into Gnomeregan without a march through the dwarf-held mountains of Dun Morogh. Scooty is proud of it: it has exploded only a dozen or so times, and he swears it is all fixed now.', 'quest 2842 description (word from Kernobee; Scooty and I built the Transpolyporter 6000; or run through the dwarf infested mountains of Dun Morogh) and reward text (only exploded a dozen or so times; all fixed up); quest_template_addon 2842 PrevQuestID -2841 (offered only while 2841 is in the log); creature_template 3413 Sovik, Engineering Supplies; 7853 Scooty, Chief Engineer'),
(72105, 2, 0, 255, 'The blueprints reached Orgrimmar, pried from Thermaplugg''s safe with the combination only he had known. Nogg crowed that he had known it could be done, though Sovik had his doubts. Now, he says, it is only a matter of time before the goblins work out every gnomish innovation in the rig and make them goblin innovations for their new shredders.', 'quest 2841 description (combination known only to Thermaplugg) and reward text; gameobject 142477 Thermaplugg''s Safe, single spawn on map 90'),
(72106, 1, 0, 255, 'The goblin Kernobee learned more than the Dark Irons wished. He found that they had a hand in making the new gnomish rig, and for that they caught him, beat him nearly to death and threw him to the troggs. Should he escape, he means to carry the warning to Ratchet.', 'quest 2904 description (captured by dark iron dwarves; warn Tinkerwiz of the dark iron''s involvement in the making of that super rig)'),
(72106, 2, 0, 255, 'The clan sent more than soldiers. Among the agents in the deep tunnels stood the Dark Iron Ambassador, a sorcerer who wrapped himself in frost and flame and called up burning servants to fight at his side. He fell there all the same, and whatever embassy brought him to a ruin of troggs, lepers and machines went unspoken to the grave with him.', 'creature 6228 Dark Iron Ambassador, single spawn at -718,565 among the agents; smart_scripts 6228 (despawns at spawn 85 percent of the time: a rare; Frost Armor, Fireball, Fire Shield, Summon Burning Servant); warcraft.wiki.gg/wiki/Gnomeregan_(instance) (Dark Iron Ambassador, rare, in the Tinkers'' Court entrance tunnel)'),
(72106, 3, 0, 255, 'One ring, taken from a Dark Iron and scrubbed clean, bore the seal of Ironforge and the initials TdK. Talvash del Kissel knew it for his own work: before Gnomeregan fell he kept a small shop there, and the ring may have belonged to someone who never got out. That Dark Irons had it, he grumbled, adds one more layer to the nine conspiracies already about, and the authorities might want to know.', 'quest 2947 description (seal of Ironforge, initials TdK) and reward text (small shop in Gnomeregan; someone who didn''t make it out; Dark Iron dwarves had this; a new layer of conspiracy on the nine already; maybe the authorities would like to know)'),
(72106, 4, 0, 255, 'Another such ring bore the seal of Orgrimmar and letters beginning NOG. Nogg swore it was not his, but the story caught his interest. For years the gnomes were a joke, he reasons, and now almost overnight they build better rigs than the goblins; perhaps they stole the Dark Irons'' golem plans and improved on them, in which case the Dark Irons would want serious payback. It is worth investigating, he says.', 'quest 2949 description (seal of Orgrimmar, NOG...) and reward text (not mine, but interesting; maybe the gnomes stole their crazy golem plans and modified them; the Dark Irons would want major payback)'),
(72107, 1, 0, 255, 'One of them is the Electrocutioner 6000, which meets intruders with a cry of electric justice and lashes them with shocks, megavolts and bolts of lightning that leap from one foe to the next, until at last it is torn down and its current goes dead.', 'creature_text 6235 (Electric justice!); smart_scripts 6235 (Shock, Megavolt, Chain Bolt), the same in the module''s dungeon_gnomeregan.sql; creature 6235 single spawn on map 90'),
(72107, 2, 0, 255, 'Another is the Crowd Pummeler 9-60, a hulking construct that does exactly what its name promises. It pummels, tramples and sweeps its great arms through every foe within reach at once, and it does not stop until it has been broken down to scrap.', 'smart_scripts 6229 (Crowd Pummel, Trample, Arcing Smash); creature 6229 single spawn on map 90'),
(72107, 3, 0, 255, 'Some of the wreckage is put to use. In Stormwind, Shoni the Shilent needed spare parts to get her fleet of gyrodrillmatic excavationators to Dun Morogh, and she had heard that bots and mechs roam Gnomeregan like cattle on an open range. Two dozen sets of robot guts were enough to fix one excavationator; by her count, three hundred ninety-eight remain.', 'quest 2928 description and reward text');
